//! A hand-built, minimal API bundle for unit tests: one API root with a plain `u32` stream at id 1, nothing
//! else. Real bundles are generated by `wire_weaver` codegen; this one exists so [schema](crate::schema) and
//! [decode](crate::decode) have something to resolve and decode against without a device or a full build.

use wire_weaver::shrink_wrap::UNib32;
use ww_numeric::{NumericAnyTypeOwned, NumericBaseType};
use ww_self::{
    ApiBundleOwned, ApiItemKindOwned, ApiItemOwned, ApiLevelOwned, Multiplicity, TypeOwned,
};

/// `trait Root { stream!(value: u32); }`, id 1.
pub fn one_stream_bundle() -> ApiBundleOwned {
    ApiBundleOwned {
        magic: ww_self::MAGIC,
        ww_self_version: ww_self::VERSION,
        root: ApiLevelOwned {
            docs: vec![],
            crate_idx: UNib32(0),
            trait_name: "Root".to_string(),
            items: vec![ApiItemOwned {
                id: UNib32(1),
                kind: ApiItemKindOwned::Stream {
                    ty: TypeOwned::NumericAny(NumericAnyTypeOwned::Base(NumericBaseType::U32)),
                    is_up: true,
                },
                multiplicity: Multiplicity::Flat,
                since: None,
                ident: "value".to_string(),
                docs: vec![],
                optional: None,
            }],
        },
        types: vec![],
        traits: vec![],
        ext_crates: vec![],
        root_omitted: None,
    }
}
